'Übungsordner für PowerShell Serie 1' | Set-Content README.txt

steps.checkScript:
#!/usr/bin/env pwsh
if (-not (Test-Path prozesse.csv)) { 'prozesse.csv gibt es noch nicht.'; exit 1 }
$rows = @(Import-Csv prozesse.csv)
if ($rows.Count -lt 2) { 'prozesse.csv enthält zu wenige Prozesse – es sollen ALLE Prozesse sein.'; exit 1 }
foreach ($c in 'Name', 'CPU') {
  if ($c -notin $rows[0].PSObject.Properties.Name) { "In prozesse.csv fehlt die Spalte '$c'."; exit 1 }
}
$cpu = $rows | ForEach-Object { if ($_.CPU) { [double]::Parse($_.CPU, [cultureinfo]::InvariantCulture) } else { 0 } }
for ($i = 1; $i -lt $cpu.Count; $i++) {
  if ($cpu[$i] -gt $cpu[$i - 1]) { 'Die Liste ist nicht absteigend nach CPU sortiert.'; exit 1 }
}
"Richtig: $($rows.Count) Prozesse, absteigend nach CPU sortiert."

#!/usr/bin/env pwsh
if (-not (Test-Path top10.csv)) { 'top10.csv gibt es noch nicht.'; exit 1 }
$rows = @(Import-Csv top10.csv)
if ($rows.Count -lt 1) { 'top10.csv ist leer.'; exit 1 }
if ($rows.Count -gt 10) { "top10.csv enthält $($rows.Count) Einträge – es sollen höchstens 10 sein."; exit 1 }
if ('CPU' -notin $rows[0].PSObject.Properties.Name) { "In top10.csv fehlt die Spalte 'CPU'."; exit 1 }
$cpu = $rows | ForEach-Object { if ($_.CPU) { [double]::Parse($_.CPU, [cultureinfo]::InvariantCulture) } else { 0 } }
for ($i = 1; $i -lt $cpu.Count; $i++) {
  if ($cpu[$i] -gt $cpu[$i - 1]) { 'top10.csv ist nicht absteigend nach CPU sortiert.'; exit 1 }
}
"Richtig: $($rows.Count) Prozesse mit der höchsten CPU-Zeit."

#!/usr/bin/env pwsh
if (-not (Test-Path A4.txt)) { 'A4.txt gibt es noch nicht.'; exit 1 }
$t = Get-Content A4.txt -Raw
if ([string]::IsNullOrWhiteSpace($t)) { 'A4.txt ist leer.'; exit 1 }
if ($t -notmatch 'ProcessName|Name') { 'A4.txt sieht nicht nach einer Prozessliste aus (Spalte Name/ProcessName fehlt).'; exit 1 }
'Richtig: A4.txt enthält die Prozessliste.'

#!/usr/bin/env pwsh
if (-not (Test-Path A4.csv)) { 'A4.csv gibt es noch nicht.'; exit 1 }
if (-not (Test-Path A4.xml)) { 'A4.xml gibt es noch nicht.'; exit 1 }
$csv = @(Import-Csv A4.csv)
if ($csv.Count -lt 1 -or $csv.Count -gt 10) { "A4.csv soll 1 bis 10 Prozesse enthalten (gefunden: $($csv.Count))."; exit 1 }
if (-not ($csv[0].PSObject.Properties.Name -match 'Name')) { 'A4.csv enthält keine Prozessnamen.'; exit 1 }
try { $xml = @(Import-Clixml A4.xml) } catch { 'A4.xml lässt sich nicht mit Import-Clixml einlesen – verwende Export-Clixml.'; exit 1 }
if ($xml.Count -lt 1 -or $xml.Count -gt 10) { "A4.xml soll 1 bis 10 Prozesse enthalten (gefunden: $($xml.Count))."; exit 1 }
'Richtig: A4.csv und A4.xml enthalten die Top-Prozesse.'

#!/usr/bin/env pwsh
if (-not (Test-Path services.csv)) { 'services.csv gibt es noch nicht.'; exit 1 }
$rows = @(Import-Csv services.csv)
$all = @(Get-Service).Count
if ($rows.Count -ne $all) { "services.csv enthält $($rows.Count) Services, es gibt aber $all."; exit 1 }
if ('Status' -notin $rows[0].PSObject.Properties.Name) { "In services.csv fehlt die Spalte 'Status'."; exit 1 }
$rank = @{ Stopped = 1; StartPending = 2; StopPending = 3; Running = 4; Paused = 7 }
$v = $rows | ForEach-Object { $rank["$($_.Status)"] }
$asc = $true; $desc = $true
for ($i = 1; $i -lt $v.Count; $i++) { if ($v[$i] -lt $v[$i - 1]) { $asc = $false }; if ($v[$i] -gt $v[$i - 1]) { $desc = $false } }
if (-not ($asc -or $desc)) { 'services.csv ist nicht nach Status sortiert.'; exit 1 }
'Richtig: alle Services, nach Status sortiert.'

#!/usr/bin/env pwsh
if (-not (Test-Path rot.ps1)) { 'rot.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content rot.ps1 -Raw
if ($src -notmatch '(?i)ForegroundColor\s+[''"]?Red|Foreground\.Red|\e\[31m') { 'rot.ps1 gibt nichts in roter Farbe aus (z. B. Write-Host … -ForegroundColor Red).'; exit 1 }
$out = & pwsh -NoProfile -NonInteractive -File ./rot.ps1 *>&1 | Out-String
if ($LASTEXITCODE -ne 0) { "rot.ps1 bricht mit einem Fehler ab:`n$out"; exit 1 }
if ($out -notmatch 'Spooler' -or $out -notmatch 'wuauserv') { 'Die Ausgabe von rot.ps1 enthält nicht alle Services.'; exit 1 }
if ($out -notmatch 'Running|Stopped') { 'Die Ausgabe von rot.ps1 enthält keinen Status.'; exit 1 }
'Richtig: rot.ps1 gibt Name und Status rot aus.'

#!/usr/bin/env pwsh
if (-not (Test-Path farbe.ps1)) { 'farbe.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content farbe.ps1 -Raw
if ($src -notmatch '(?i)\bif\b') { 'farbe.ps1 verwendet keine if-Abfrage.'; exit 1 }
if ($src -notmatch '(?i)Green' -or $src -notmatch '(?i)Red') { 'farbe.ps1 soll Rot UND Grün verwenden.'; exit 1 }
if ($src -notmatch '(?i)Running|Stopped') { 'farbe.ps1 prüft den Status nicht (Running/Stopped).'; exit 1 }
$out = & pwsh -NoProfile -NonInteractive -File ./farbe.ps1 *>&1 | Out-String
if ($LASTEXITCODE -ne 0) { "farbe.ps1 bricht mit einem Fehler ab:`n$out"; exit 1 }
if ($out -notmatch 'Spooler' -or $out -notmatch 'wuauserv') { 'Die Ausgabe von farbe.ps1 enthält nicht alle Services.'; exit 1 }
'Richtig: Services rot/grün nach Status.'

#!/usr/bin/env pwsh
if (-not (Test-Path services.html)) { 'services.html gibt es noch nicht.'; exit 1 }
$h = Get-Content services.html -Raw
if ($h -notmatch '(?i)<table') { 'services.html enthält keine HTML-Tabelle (ConvertTo-Html verwenden).'; exit 1 }
if ($h -notmatch 'Spooler' -or $h -notmatch 'wuauserv') { 'services.html enthält nicht alle Services.'; exit 1 }
'Richtig: services.html ist eine HTML-Tabelle der Services.'

#!/usr/bin/env pwsh
if (-not (Test-Path dateien.ps1)) { 'dateien.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content dateien.ps1 -Raw
if ($src -notmatch '/usr/bin') { 'dateien.ps1 soll das Verzeichnis /usr/bin auflisten.'; exit 1 }
$out = & pwsh -NoProfile -NonInteractive -File ./dateien.ps1 *>&1 | Out-String -Width 300
if ($LASTEXITCODE -ne 0) { "dateien.ps1 bricht mit einem Fehler ab:`n$($out.Substring(0, [Math]::Min(600, $out.Length)))"; exit 1 }
if ($out -notmatch '\bbash\b') { 'In der Ausgabe fehlen Dateien aus /usr/bin (z. B. bash).'; exit 1 }
if ($out -notmatch '(?i)Length|Größe|Groesse|Size') { 'Die Ausgabe zeigt keine Dateigröße (Length).'; exit 1 }
if ($out -notmatch '(?i)CreationTime|Erstell') { 'Die Ausgabe zeigt kein Erstellungsdatum (CreationTime).'; exit 1 }
'Richtig: Dateien mit Größe und Erstellungsdatum.'

#!/usr/bin/env pwsh
if (-not (Test-Path ordner.ps1)) { 'ordner.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content ordner.ps1 -Raw
if ($src -notmatch '(?i)Test-Path') { 'ordner.ps1 soll mit Test-Path prüfen, ob das Verzeichnis schon existiert.'; exit 1 }
$before = @(Get-ChildItem ./Temp -Directory -ErrorAction SilentlyContinue).Name
foreach ($run in 1..2) {
  $out = & pwsh -NoProfile -NonInteractive -File ./ordner.ps1 *>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { "ordner.ps1 bricht beim $run. Aufruf mit einem Fehler ab:`n$out"; exit 1 }
}
$dirs = @(Get-ChildItem ./Temp -Directory -ErrorAction SilentlyContinue)
if ($dirs.Count -eq 0) { 'Unter ./Temp wurde kein Verzeichnis erstellt.'; exit 1 }
$d = Get-Date
$pats = $d.ToString('yyyy-MM-dd'), $d.ToString('yyyyMMdd'), $d.ToString('dd.MM.yyyy'), $d.ToString('dd-MM-yyyy'), $d.ToString('yyyy_MM_dd')
$hit = $dirs | Where-Object { $n = $_.Name; $pats | Where-Object { $n.Contains($_) } }
if (-not $hit) { "Kein Verzeichnis unter ./Temp enthält das heutige Datum (z. B. $($pats[0]))."; exit 1 }
"Richtig: ./Temp/$($hit[0].Name) wurde erstellt."

#!/usr/bin/env pwsh
if (-not (Test-Path nachricht.txt)) { 'nachricht.txt gibt es noch nicht.'; exit 1 }
$t = (Get-Content nachricht.txt -Raw)
if ([string]::IsNullOrWhiteSpace($t)) { 'nachricht.txt ist leer.'; exit 1 }
if ($t.Trim().Length -lt 5) { 'Die Nachricht ist sehr kurz – schreib ein paar Wörter.'; exit 1 }
'Richtig: nachricht.txt enthält deine Nachricht.'

#!/usr/bin/env pwsh
if (-not (Test-Path lesen.ps1)) { 'lesen.ps1 gibt es noch nicht.'; exit 1 }
if (-not (Test-Path nachricht.txt)) { 'nachricht.txt fehlt (Schritt 3).'; exit 1 }
$expected = (Get-Content nachricht.txt -Raw).Trim()
$out = (& pwsh -NoProfile -NonInteractive -File ./lesen.ps1 *>&1 | Out-String).Trim()
if ($LASTEXITCODE -ne 0) { "lesen.ps1 bricht mit einem Fehler ab:`n$out"; exit 1 }
if (-not $out.Contains($expected)) { 'Die Ausgabe von lesen.ps1 enthält nicht den Inhalt von nachricht.txt.'; exit 1 }
'Richtig: lesen.ps1 gibt die Nachricht aus.'

#!/usr/bin/env pwsh
if (-not (Test-Path ziel -PathType Container)) { 'Den Ordner ziel/ gibt es noch nicht.'; exit 1 }
$want = @(Get-ChildItem quelle -Filter *.txt -File | Sort-Object Name).Name
$got = @(Get-ChildItem ziel -File | Sort-Object Name).Name
$missing = $want | Where-Object { $_ -notin $got }
$extra = $got | Where-Object { $_ -notin $want }
if ($missing) { "In ziel/ fehlen: $($missing -join ', ')"; exit 1 }
if ($extra) { "In ziel/ gehören nur .txt-Dateien – zu viel: $($extra -join ', ')"; exit 1 }
'Richtig: alle .txt-Dateien wurden kopiert.'

#!/usr/bin/env pwsh
if (-not (Test-Path sysinfo.ps1)) { 'sysinfo.ps1 gibt es noch nicht.'; exit 1 }
$out = & pwsh -NoProfile -NonInteractive -File ./sysinfo.ps1 *>&1 | Out-String -Width 300
if ($LASTEXITCODE -ne 0) { "sysinfo.ps1 bricht mit einem Fehler ab:`n$out"; exit 1 }
$ci = Get-ComputerInfo
if ($out -notmatch [regex]::Escape($ci.CsName)) { "Die Ausgabe enthält den Computernamen ($($ci.CsName)) nicht."; exit 1 }
if ($out -notmatch 'Windows') { 'Die Ausgabe enthält das Betriebssystem nicht.'; exit 1 }
$gb = [math]::Round($ci.CsTotalPhysicalMemory / 1GB)
if ($out -notmatch "\b$gb\b" -and $out -notmatch [regex]::Escape("$($ci.CsTotalPhysicalMemory)")) { "Die Ausgabe enthält die RAM-Größe nicht (z. B. $gb GB)."; exit 1 }
'Richtig: Computername, Betriebssystem und RAM werden angezeigt.'

#!/usr/bin/env pwsh
if (-not (Test-Path summe.ps1)) { 'summe.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content summe.ps1 -Raw
if ($src -notmatch '(?i)function\s+Get-Summe') { 'summe.ps1 enthält keine Funktion Get-Summe.'; exit 1 }
try { . ./summe.ps1 *> $null } catch { "summe.ps1 bricht mit einem Fehler ab: $_"; exit 1 }
$tests = @(@(3, 4, 7), @(10, -2, 8), @(2.5, 0.5, 3))
foreach ($t in $tests) {
  $r = Get-Summe $t[0] $t[1]
  if ([double]$r -ne $t[2]) { "Get-Summe $($t[0]) $($t[1]) liefert '$r' statt $($t[2])."; exit 1 }
}
'Richtig: Get-Summe rechnet richtig.'

#!/usr/bin/env pwsh
if (-not (Test-Path benutzer.csv)) { 'benutzer.csv gibt es noch nicht.'; exit 1 }
if (-not (Test-Path sortiert.csv)) { 'sortiert.csv gibt es noch nicht.'; exit 1 }
$b = @(Import-Csv benutzer.csv -Delimiter ';')
if ($b.Count -lt 5) { "benutzer.csv braucht mindestens 5 Einträge (gefunden: $($b.Count))."; exit 1 }
foreach ($c in 'Vorname', 'Nachname', 'Geburtsdatum') {
  if ($c -notin $b[0].PSObject.Properties.Name) { "In benutzer.csv fehlt die Spalte '$c' (Trennzeichen ';'?)."; exit 1 }
}
$s = @(Import-Csv sortiert.csv -Delimiter ';')
if ($s.Count -ne $b.Count) { "sortiert.csv enthält $($s.Count) statt $($b.Count) Benutzer (Trennzeichen ';'?)."; exit 1 }
$fmt = 'yyyy-MM-dd', 'dd.MM.yyyy', 'd.M.yyyy', 'yyyy/MM/dd'
$dates = foreach ($r in $s) {
  try { [datetime]::ParseExact($r.Geburtsdatum.Trim(), [string[]]$fmt, [cultureinfo]::InvariantCulture, 'None') }
  catch { "Ungültiges Geburtsdatum in sortiert.csv: '$($r.Geburtsdatum)'"; exit 1 }
}
for ($i = 1; $i -lt $dates.Count; $i++) {
  if ($dates[$i] -lt $dates[$i - 1]) { 'sortiert.csv ist nicht nach Alter sortiert (älteste zuerst).'; exit 1 }
}
'Richtig: Benutzer nach Alter sortiert.'

#!/usr/bin/env pwsh
if (-not (Test-Path loganalyse.ps1)) { 'loganalyse.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content loganalyse.ps1 -Raw
if ($src -notmatch '(?i)\btry\b' -or $src -notmatch '(?i)\bcatch\b') { 'Zusatzanforderung: verwende try/catch in loganalyse.ps1.'; exit 1 }
$before = Get-Date
Start-Sleep -Milliseconds 1100
$out = & pwsh -NoProfile -NonInteractive -File ./loganalyse.ps1 *>&1 | Out-String
if ($LASTEXITCODE -ne 0) { "loganalyse.ps1 endet mit Fehler (exit $LASTEXITCODE):`n$out"; exit 1 }
$rep = Get-ChildItem -Filter 'bericht_*.csv' | Where-Object LastWriteTime -ge $before.AddSeconds(-1) | Sort-Object LastWriteTime | Select-Object -Last 1
if (-not $rep) { 'Es wurde kein Bericht bericht_<Zeitstempel>.csv erstellt.'; exit 1 }
if ($rep.Name -notmatch '^bericht_.*\d{4}.*\.csv$') { "Der Dateiname $($rep.Name) enthält keinen Zeitstempel."; exit 1 }
$rows = @(Import-Csv $rep.FullName)
if ($rows.Count -eq 1 -and $rows[0].PSObject.Properties.Name -contains 'Level;Anzahl') { $rows = @(Import-Csv $rep.FullName -Delimiter ';') }
foreach ($lvl in 'ERROR', 'WARNING', 'INFO') {
  $want = @(Get-Content app.log | Where-Object { ($_ -split '\s+')[2] -eq $lvl }).Count
  $row = $rows | Where-Object { $_.Level -eq $lvl }
  if (-not $row) { "Im Bericht fehlt die Zeile für $lvl (Spalten Level und Anzahl)."; exit 1 }
  if ([int]$row.Anzahl -ne $want) { "$lvl ist im Bericht $($row.Anzahl), richtig wäre $want."; exit 1 }
}
"Richtig: $($rep.Name) mit korrekten Zahlen."

#!/usr/bin/env pwsh
if (-not (Test-Path monitor.ps1)) { 'monitor.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content monitor.ps1 -Raw
if ($src -notmatch '(?i)\bparam\s*\(') { 'Zusatzanforderung: monitor.ps1 braucht param(...) mit -Dienste.'; exit 1 }
if ($src -notmatch '(?i)\btry\b' -or $src -notmatch '(?i)\bcatch\b') { 'Zusatzanforderung: verwende try/catch in monitor.ps1.'; exit 1 }
Remove-Item monitor.log -ErrorAction SilentlyContinue
$out = & pwsh -NoProfile -NonInteractive -File ./monitor.ps1 *>&1 | Out-String
if (-not (Test-Path monitor.log)) { "monitor.ps1 hat keine monitor.log geschrieben.`n$out"; exit 1 }
$log = @(Get-Content monitor.log | Where-Object { $_.Trim() })
foreach ($d in 'Spooler', 'wuauserv', 'BITS') {
  if (-not ($log | Where-Object { $_ -match "\b$d\b" })) { "In monitor.log fehlt eine Zeile für $d."; exit 1 }
}
$wu = $log | Where-Object { $_ -match '\bwuauserv\b' } | Select-Object -First 1
if ($wu -cnotmatch 'STOPPED|GESTOPPT') { 'Der gestoppte Dienst wuauserv ist in monitor.log nicht deutlich markiert (STOPPED oder GESTOPPT in Großbuchstaben).'; exit 1 }
$sp = $log | Where-Object { $_ -match '\bSpooler\b' } | Select-Object -First 1
if ($sp -cmatch 'STOPPED|GESTOPPT') { 'Spooler läuft – er darf nicht als gestoppt markiert sein.'; exit 1 }
Remove-Item monitor.log
& pwsh -NoProfile -NonInteractive -File ./monitor.ps1 -Dienste 'Fax' *> $null
if (-not (Test-Path monitor.log) -or ((Get-Content monitor.log -Raw) -notmatch '\bFax\b')) { 'Mit -Dienste Fax wird Fax nicht protokolliert – der Parameter funktioniert nicht.'; exit 1 }
'Richtig: monitor.log protokolliert die Dienste und markiert gestoppte.'

#!/usr/bin/env pwsh
if (-not (Test-Path backup.ps1)) { 'backup.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content backup.ps1 -Raw
if ($src -notmatch '(?i)\bparam\s*\(') { 'Zusatzanforderung: backup.ps1 braucht param(...) mit -Quelle und -Ziel.'; exit 1 }
$ziel = '/tmp/oshell-backup-check'
Remove-Item $ziel -Recurse -Force -ErrorAction SilentlyContinue
foreach ($i in 1..7) {
  $out = & pwsh -NoProfile -NonInteractive -File ./backup.ps1 -Quelle ./daten -Ziel $ziel *>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { "backup.ps1 endet beim $i. Aufruf mit Fehler:`n$out"; exit 1 }
  if ($i -lt 7) { Start-Sleep -Milliseconds 1100 }
}
$b = @(Get-ChildItem $ziel -Directory -Filter 'backup_*')
if ($b.Count -ne 5) { "Nach 7 Aufrufen sollen genau 5 Backups übrig sein, gefunden: $($b.Count)."; exit 1 }
foreach ($d in $b) {
  if (-not (Test-Path (Join-Path $d.FullName 'bericht.txt'))) { "$($d.Name) enthält die Dateien aus daten/ nicht."; exit 1 }
}
Remove-Item $ziel -Recurse -Force
'Richtig: Backups mit Zeitstempel, die letzten 5 bleiben.'

#!/usr/bin/env pwsh
foreach ($f in 'hash-referenz.ps1', 'hash-pruefen.ps1') { if (-not (Test-Path $f)) { "$f gibt es noch nicht."; exit 1 } }
$t = '/tmp/oshell-hash-check'
Remove-Item $t -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory $t | Out-Null
Copy-Item ./daten "$t/daten" -Recurse
$ref = "$t/referenz.csv"
$o1 = & pwsh -NoProfile -NonInteractive -File ./hash-referenz.ps1 -Pfad "$t/daten" -Referenz $ref *>&1 | Out-String
if (-not (Test-Path $ref)) { "hash-referenz.ps1 hat keine Referenzdatei geschrieben (-Referenz).`n$o1"; exit 1 }
$refText = Get-Content $ref -Raw
$h = (Get-FileHash "$t/daten/bericht.txt" -Algorithm SHA256).Hash
if ($refText -notmatch $h) { 'Die Referenzdatei enthält keine SHA256-Prüfsummen (z. B. für bericht.txt).'; exit 1 }
'GEÄNDERT' | Add-Content "$t/daten/notizen.txt"
Remove-Item "$t/daten/bild.dat"
'ganz neu' | Set-Content "$t/daten/neu.txt"
$o2 = & pwsh -NoProfile -NonInteractive -File ./hash-pruefen.ps1 -Pfad "$t/daten" -Referenz $ref *>&1 | Out-String -Width 300
foreach ($n in 'notizen.txt', 'bild.dat', 'neu.txt') {
  if ($o2 -notmatch [regex]::Escape($n)) { "hash-pruefen.ps1 meldet $n nicht (verändert/gelöscht/neu).`nAusgabe:`n$o2"; exit 1 }
}
foreach ($ok in 'bericht.txt', 'inventar.txt') {
  $line = ($o2 -split "`n") | Where-Object { $_ -match [regex]::Escape($ok) }
  if ($line -and ($line -match '(?i)neu|gel(ö|oe)scht|ver(ä|ae)ndert|changed|deleted|new')) { "$ok ist unverändert, wird aber als Änderung gemeldet."; exit 1 }
}
Remove-Item $t -Recurse -Force
'Richtig: neue, gelöschte und veränderte Dateien werden erkannt.'

#!/usr/bin/env pwsh
if (-not (Test-Path admin.ps1)) { 'admin.ps1 gibt es noch nicht.'; exit 1 }
$t = '/tmp/oshell-admin-check'
Remove-Item $t -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory "$t/akten" -Force | Out-Null
'a' | Set-Content "$t/akten/eins.txt"; 'b' | Set-Content "$t/akten/zwei.txt"
$run = { param($a) & pwsh -NoProfile -NonInteractive -File ./admin.ps1 @a *>&1 | Out-String -Width 300 }
$o = & $run @('-Mode', 'Quatsch', '-Path', "$t/akten")
if ($LASTEXITCODE -eq 0) { "Ein ungültiger -Mode (Quatsch) muss mit Exit-Code ungleich 0 enden.`n$o"; exit 1 }
$o = & $run @('-Mode', 'List', '-Path', "$t/akten")
if ($LASTEXITCODE -ne 0 -or $o -notmatch 'eins\.txt' -or $o -notmatch 'zwei\.txt') { "-Mode List soll die Dateien auflisten.`n$o"; exit 1 }
$o = & $run @('-Mode', 'Archive', '-Path', "$t/akten")
if (-not (Test-Path "$t/akten.zip")) { "-Mode Archive soll $t/akten.zip erstellen.`n$o"; exit 1 }
$o = & $run @('-Mode', 'Delete', '-Path', "$t/akten", '-WhatIf')
if (-not (Test-Path "$t/akten/eins.txt")) { '-Mode Delete -WhatIf darf nichts löschen!'; exit 1 }
$o = & $run @('-Mode', 'Delete', '-Path', "$t/akten")
if (@(Get-ChildItem "$t/akten" -File).Count -ne 0) { "-Mode Delete soll die Dateien löschen.`n$o"; exit 1 }
Remove-Item $t -Recurse -Force
'Richtig: List, Archive, Delete und -WhatIf funktionieren.'

#!/usr/bin/env pwsh
if (-not (Test-Path inventar.ps1)) { 'inventar.ps1 gibt es noch nicht.'; exit 1 }
$src = Get-Content inventar.ps1 -Raw
if ($src -notmatch '(?i)Get-CimInstance') { 'inventar.ps1 soll die Daten mit Get-CimInstance sammeln.'; exit 1 }
if ($src -notmatch '(?i)\btry\b' -or $src -notmatch '(?i)\bcatch\b') { 'Zusatzanforderung: verwende try/catch (für nicht erreichbare Rechner).'; exit 1 }
Remove-Item inventar.csv, inventar.html -ErrorAction SilentlyContinue
$out = & pwsh -NoProfile -NonInteractive -File ./inventar.ps1 *>&1 | Out-String -Width 300
if (-not (Test-Path inventar.csv)) { "inventar.csv wurde nicht erstellt (bricht das Skript beim offline-Rechner ab?).`n$out"; exit 1 }
if (-not (Test-Path inventar.html)) { 'inventar.html wurde nicht erstellt.'; exit 1 }
$rows = @(Import-Csv inventar.csv)
if ('Computer' -notin $rows[0].PSObject.Properties.Name) { "inventar.csv braucht eine Spalte 'Computer'."; exit 1 }
$online = $rows | Where-Object { $_.Computer -match '(?i)PC-R101-01' }
if (-not $online) { 'Der Rechner PC-R101-01 fehlt in inventar.csv.'; exit 1 }
if ($rows.Count -lt 3) { "inventar.csv soll die 3 erreichbaren Rechner enthalten (gefunden: $($rows.Count))."; exit 1 }
$all = ($rows | ConvertTo-Csv | Out-String)
if ($all -notmatch 'Windows') { 'inventar.csv enthält kein Betriebssystem.'; exit 1 }
$cpu = (Get-CimInstance Win32_Processor -ComputerName PC-R101-01).Name
if ($all -notmatch [regex]::Escape($cpu)) { 'inventar.csv enthält die CPU nicht.'; exit 1 }
$h = Get-Content inventar.html -Raw
